import{_ as e,o as a,c as t,a2 as l}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"ZViewerCLI 本地代理","description":"","frontmatter":{},"headers":[],"relativePath":"cli/index.md","filePath":"cli/index.md","lastUpdated":1785772843000}'),s={name:"cli/index.md"};function r(n,i,o,d,p,h){return a(),t("div",null,[...i[0]||(i[0]=[l(`<h1 id="zviewercli-本地代理" tabindex="-1">ZViewerCLI 本地代理 <a class="header-anchor" href="#zviewercli-本地代理" aria-label="Permalink to &quot;ZViewerCLI 本地代理&quot;">​</a></h1><h2 id="功能概述" tabindex="-1">功能概述 <a class="header-anchor" href="#功能概述" aria-label="Permalink to &quot;功能概述&quot;">​</a></h2><p>ZViewerCLI 是一个运行在你本地的轻量级代理程序，用于解决浏览器无法直接使用你的 Bilibili Cookie 获取高画质视频的问题。</p><p>简单来说：<strong>装上 CLI，你就能在 ZViewer 中观看 Bilibili 大会员画质的视频了。</strong></p><hr><h2 id="为什么需要-zviewercli" tabindex="-1">为什么需要 ZViewerCLI？ <a class="header-anchor" href="#为什么需要-zviewercli" aria-label="Permalink to &quot;为什么需要 ZViewerCLI？&quot;">​</a></h2><p>在 ZViewer 中直接解析 Bilibili 视频时，存在三个限制：</p><ol><li><strong>Cookie 安全</strong>：浏览器无法安全地将你的 Bilibili Cookie 发送到服务端（Cookie 应该留在你的电脑上）</li><li><strong>CORS 与防盗链</strong>：Bilibili CDN 对请求头（Referer、Origin、User-Agent）有严格要求，浏览器直接请求容易被拦截</li><li><strong>画质限制</strong>：服务端配置的 Bilibili Cookie 可能不是大会员，无法获取 1080P+ / 4K 等高画质</li></ol><p>ZViewerCLI 的解决方案：<strong>Cookie 只留在你的本机，视频解析和流请求都在本地完成</strong>，再转发给浏览器，完美绕过以上限制。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><ul><li><strong>本地 Cookie 解析</strong>：使用你自己的 Bilibili Cookie 解析视频，支持大会员高画质</li><li><strong>视频流代理</strong>：代理 Bilibili CDN 视频/音频流，注入正确的请求头，绕过 CORS 与防盗链</li><li><strong>CDN 自动切换</strong>：单个 CDN 连接失败时，自动尝试备用 CDN 地址</li><li><strong>WebSocket 房间注册</strong>：自动向 ZViewer 房间注册，前端可自动发现并启用</li><li><strong>二维码登录</strong>：内置 Bilibili 二维码登录页面，无需手动复制 Cookie</li><li><strong>本地配置页面</strong>：启动后自动打开浏览器配置页，填写后端地址、房间 ID、Cookie 即可连接</li><li><strong>断线自动重连</strong>：与 ZViewer 后端断开后，使用指数退避策略自动重连</li></ul><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────┐     WebSocket      ┌─────────────────┐</span></span>
<span class="line"><span>│   ZViewer 后端   │  ◄──────────────►  │  ZViewerCLI     │</span></span>
<span class="line"><span>│  (房间状态同步)  │                     │  (你的电脑上)    │</span></span>
<span class="line"><span>└─────────────────┘                     └────────┬────────┘</span></span>
<span class="line"><span>       ▲                                         │</span></span>
<span class="line"><span>       │ Socket.IO 同步播放状态                    │ 本地解析/代理</span></span>
<span class="line"><span>       │                                         ▼</span></span>
<span class="line"><span>┌──────┴──────────┐                    ┌─────────────────┐</span></span>
<span class="line"><span>│   你的浏览器      │  ◄─ 本地代理 URL ──│  Bilibili CDN   │</span></span>
<span class="line"><span>│  (ZViewer 前端)   │    (绕过 CORS)    │  (视频/音频流)   │</span></span>
<span class="line"><span>└─────────────────┘                    └─────────────────┘</span></span></code></pre></div><p>核心流程：</p><ol><li>你在本地启动 ZViewerCLI，配置 ZViewer 后端地址、房间 ID 和 Bilibili Cookie</li><li>ZViewerCLI 通过 WebSocket 连接到 ZViewer 后端，向房间注册自己的代理地址</li><li>当前端检测到房间内有 CLI 代理可用时，优先将 Bilibili 视频解析请求发送给本地 CLI</li><li>CLI 使用你的本地 Cookie 解析视频，返回代理后的视频/音频 URL</li><li>浏览器请求本地代理地址，CLI 再向上游 Bilibili CDN 请求真实数据并转发给浏览器</li></ol><hr><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><h3 id="第一步-下载" tabindex="-1">第一步：下载 <a class="header-anchor" href="#第一步-下载" aria-label="Permalink to &quot;第一步：下载&quot;">​</a></h3><p>从 <a href="https://github.com/Zero-wyc/ZViewerCLI/releases" target="_blank" rel="noreferrer">ZViewerCLI Releases</a> 下载对应你操作系统的版本：</p><table tabindex="0"><thead><tr><th>操作系统</th><th>下载文件</th></tr></thead><tbody><tr><td>Windows amd64</td><td><code>zviewer-cli-windows-amd64.exe</code></td></tr><tr><td>macOS Apple Silicon</td><td><code>zviewer-cli-darwin-arm64</code></td></tr><tr><td>Linux amd64</td><td><code>zviewer-cli-linux-amd64</code></td></tr><tr><td>Linux arm64</td><td><code>zviewer-cli-linux-arm64</code></td></tr></tbody></table><h3 id="第二步-启动" tabindex="-1">第二步：启动 <a class="header-anchor" href="#第二步-启动" aria-label="Permalink to &quot;第二步：启动&quot;">​</a></h3><p><strong>Windows</strong>：双击 <code>zviewer-cli-windows-amd64.exe</code>，或在终端中运行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">zviewer-cli-windows-amd64.exe</span></span></code></pre></div><p><strong>macOS / Linux</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zviewer-cli-darwin-arm64</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./zviewer-cli-darwin-arm64</span></span></code></pre></div><p>启动后，手动访问 <code>http://127.0.0.1:9333</code> 进入配置页面。</p><h3 id="第三步-配置并连接" tabindex="-1">第三步：配置并连接 <a class="header-anchor" href="#第三步-配置并连接" aria-label="Permalink to &quot;第三步：配置并连接&quot;">​</a></h3><p>在配置页面填写：</p><ol><li><strong>ZViewer 后端地址</strong>：例如 <code>http://localhost:3333</code> 或 <code>https://your-domain.com</code></li><li><strong>房间 ID</strong>：你想加入的房间号</li><li><strong>Bilibili Cookie</strong>：可通过二维码登录自动获取，或手动粘贴</li></ol><p>点击「连接」按钮，CLI 会验证 Cookie 并注册到房间。</p><h3 id="第四步-在房间中启用" tabindex="-1">第四步：在房间中启用 <a class="header-anchor" href="#第四步-在房间中启用" aria-label="Permalink to &quot;第四步：在房间中启用&quot;">​</a></h3><ol><li>进入 ZViewer 房间</li><li>在添加 Bilibili 视频时，打开「Bilibili 解析设置」</li><li>开启 <strong>「CLI 本地高画质代理」</strong> 开关</li><li>此时播放器会通过本地 CLI 加载视频，享受大会员画质</li></ol><blockquote><p>如果房间内没有检测到 CLI 代理，开关会显示为不可用状态。请确认 CLI 已成功连接。</p></blockquote><hr><h2 id="与-zviewer-的关系" tabindex="-1">与 ZViewer 的关系 <a class="header-anchor" href="#与-zviewer-的关系" aria-label="Permalink to &quot;与 ZViewer 的关系&quot;">​</a></h2><p>ZViewerCLI 是 ZViewer 的<strong>可选配套组件</strong>。不装 CLI 也能正常使用 ZViewer 的基础解析功能。</p><table tabindex="0"><thead><tr><th>场景</th><th>无 CLI</th><th>有 CLI</th></tr></thead><tbody><tr><td>普通 B 站视频</td><td>✅ 正常播放</td><td>✅ 正常播放</td></tr><tr><td>大会员专享视频</td><td>❌ 无法播放</td><td>✅ 可播放</td></tr><tr><td>高画质（1080P+/4K）</td><td>取决于服务端配置</td><td>✅ 你的个人大会员权益</td></tr><tr><td>视频流稳定性</td><td>受 CORS 限制</td><td>✅ 本地代理，稳定可靠</td></tr></tbody></table><p>ZViewer 主项目负责房间状态同步、用户管理、播放控制；ZViewerCLI 负责本地化的 Bilibili 解析与流代理。两者通过 WebSocket 和本地 HTTP API 协作。</p><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>查看<a href="/cli/guide">使用指南</a>——命令行参数、构建方法、常见问题</li></ul>`,42)])])}const g=e(s,[["render",r]]);export{b as __pageData,g as default};
